/// <summary>
/// Extension of class <c>SalesPackingSlipController</c>
/// </summary>
[ExtensionOf(classStr(SalesPackingSlipController))]
final class KPMGSalesPackingSlipController_Extension
{
}

Method.Source:
    /// <summary>
    /// Gets the report header title.
    /// </summary>
    /// <returns>
    /// The report header title.
    /// </returns>
    public str  documentTitle()
    {
        str documentTitle = next documentTitle();

        if (documentTitle == literalStr("@SYS70796"))
        {
            documentTitle = literalStr("@KPMGAddOn:ProformaDeliveryNoteCopy");
        }
        else if (documentTitle == literalStr("@SYS24430"))
        {
            documentTitle = literalStr("@KPMGAddOn:DeliveryNoteCopy");
        }
        else if ( documentTitle == literalStr("@SYS12874"))
        {
            documentTitle = literalStr("@KPMGAddOn:ProformaDeliveryNote");
        }
        else if (documentTitle == literalStr("@SYS11549"))
        {
            documentTitle = literalStr("@KPMGAddOn:DeliveryNote");
        }    

        return documentTitle ;
    }
